// Parse RSS / Atom feed and emit one item per article.
// Pure-JS — no external libs (n8n Code node restriction).

const src = $input.first().json;
const body = src.body || src.data || '';
const sourceMeta = $('Loop Over Sources').first().json;

if (!body || typeof body !== 'string') {
  return [];
}

function stripCdata(s) {
  return String(s || '')
    .replace(/<!\[CDATA\[(.*?)\]\]>/gs, '$1')
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractTag(block, tag) {
  const re = new RegExp(`<${tag}[^>]*>([\s\S]*?)<\/${tag}>`, 'i');
  const m = block.match(re);
  return m ? stripCdata(m[1]) : '';
}

function extractAttr(block, tag, attr) {
  const re = new RegExp(`<${tag}[^>]*${attr}="([^"]+)"`, 'i');
  const m = block.match(re);
  return m ? m[1] : '';
}

// Cut into <item> (RSS) or <entry> (Atom) blocks
const itemRe = /<(item|entry)[\s\S]*?<\/(item|entry)>/gi;
const blocks = body.match(itemRe) || [];

const maxAgeDays = 14;
const cutoff = Date.now() - maxAgeDays * 24 * 60 * 60 * 1000;

const out = [];
for (const block of blocks.slice(0, 25)) {
  const title = extractTag(block, 'title');
  if (!title) continue;

  let link = extractTag(block, 'link') || extractAttr(block, 'link', 'href');
  link = (link || '').trim();

  const description =
    extractTag(block, 'description') ||
    extractTag(block, 'summary') ||
    extractTag(block, 'content');

  const pubRaw =
    extractTag(block, 'pubDate') ||
    extractTag(block, 'updated') ||
    extractTag(block, 'published') ||
    extractTag(block, 'dc:date');

  const observed = pubRaw ? new Date(pubRaw) : new Date();
  if (Number.isNaN(observed.getTime())) continue;
  if (observed.getTime() < cutoff) continue;

  out.push({
    json: {
      sourceMeta,
      article: {
        title,
        link,
        description,
        observedAt: observed.toISOString(),
      },
    },
  });
}

return out;

// Classify the article into a hiring signal type, compute impact and
// confidence, and assemble the canonical Hiring Radar payload.
// Tolerates unknown classifications (skips silently).

const SIGNAL_RULES = [
  { type: 'insolvency',         re: /insolven[zc]|bankruptcy|chapter\s*11/i,                   impact: -38, conf: 0.92 },
  { type: 'restructuring',      re: /restructur|reorgan|umstrukturier|stellenabbau|layoff/i,   impact: -22, conf: 0.78 },
  { type: 'mna_buy',            re: /acquir(es|ed|ition)|\b(buys|kauft|übernimmt|takeover)/i,   impact:  24, conf: 0.82 },
  { type: 'mna_sell',           re: /divest|sells .* (unit|division|business)|verkauft/i,      impact: -14, conf: 0.78 },
  { type: 'gf_change',          re: /\bnew (ceo|cto|cfo|coo|chief)|appoint(s|ed)|ernennt/i,    impact:  10, conf: 0.74 },
  { type: 'patent_filing',      re: /patent (filing|application|granted)|patentanmeldung/i,    impact:  16, conf: 0.78 },
  { type: 'funding_grant',      re: /raised|series\s*[a-e]|funding round|förderung|grant/i,    impact:  22, conf: 0.86 },
  { type: 'location_expansion', re: /opens? .*office|new office|niederlassung|expand|standort/i, impact: 20, conf: 0.80 },
  { type: 'job_spike',          re: /hiring spree|job(s)? (spike|boom)|stellenanzeigen/i,      impact:  26, conf: 0.78 },
  { type: 'employee_growth',    re: /headcount|workforce growth|mitarbeiter ?wachstum/i,        impact:  20, conf: 0.74 },
  { type: 'product_launch',     re: /launch(es|ed)|unveil(s|ed)|stellt vor|markteinführung/i,  impact:  14, conf: 0.72 },
  { type: 'new_business_unit',  re: /new (division|business unit|geschäftsbereich)/i,          impact:  18, conf: 0.78 },
];

const items = [];
for (const it of $input.all()) {
  const sourceMeta = it.json.sourceMeta || {};
  const article = it.json.article || {};
  const haystack = `${article.title || ''} ${article.description || ''}`;

  let pick = null;
  for (const rule of SIGNAL_RULES) {
    if (rule.re.test(haystack)) { pick = rule; break; }
  }

  // Press release fallback only if the source explicitly opts in
  if (!pick) {
    if (String(sourceMeta.source_type || '').toLowerCase().includes('press')) {
      pick = { type: 'press_release', impact: 6, conf: 0.55 };
    } else {
      continue; // skip un-classifiable rows
    }
  }

  // Source-trust modifier (priority 1 = high, 5 = low)
  const priority = Number(sourceMeta.priority || 3);
  const trust = Math.max(0.6, Math.min(1, 1 - (priority - 1) * 0.08));

  // Recency modifier
  const ageDays = Math.max(0, (Date.now() - new Date(article.observedAt).getTime()) / 86400000);
  const recencyBoost = ageDays <= 1 ? 1.1 : ageDays <= 7 ? 1.0 : 0.9;

  const impact = Math.round(Math.max(-100, Math.min(100, pick.impact * recencyBoost)));
  const confidence = Math.max(0, Math.min(1, +(pick.conf * trust).toFixed(2)));

  items.push({
    json: {
      companyName: sourceMeta.company_name,
      signalType: pick.type,
      source: sourceMeta.source_type || 'rss',
      title: article.title,
      description: (article.description || '').slice(0, 500),
      impact,
      confidence,
      observedAt: article.observedAt,
      metadata: {
        url: article.link,
        region: sourceMeta.region || '',
        industry: sourceMeta.industry || '',
        country: sourceMeta.country || '',
        company_domain: sourceMeta.company_domain || '',
        workflow: 'rsg-hiring-signals-live-v1',
      },
    },
  });
}

return items;

// In-run de-dup: same companyName + signalType + observedAt collapses to one.
const seen = new Set();
const out = [];
for (const it of $input.all()) {
  const k = `${it.json.companyName}|${it.json.signalType}|${it.json.observedAt}|${(it.json.title || '').slice(0,80)}`;
  if (seen.has(k)) continue;
  seen.add(k);
  out.push(it);
}
return out;

// Build one IngestLog row per ingested article (success or error).
const rows = [];
for (const it of $input.all()) {
  const payload = it.json.body ? it.json.body : {};
  const reqJson = $('Code · De-duplicate').all()[$itemIndex]?.json || {};
  const status = it.json.statusCode ?? it.json.status ?? null;
  const ok = status && status >= 200 && status < 300;
  rows.push({
    json: {
      run_at: new Date().toISOString(),
      company_name: reqJson.companyName || '',
      signal_type: reqJson.signalType || '',
      title: reqJson.title || '',
      url: (reqJson.metadata && reqJson.metadata.url) || '',
      impact: reqJson.impact ?? '',
      confidence: reqJson.confidence ?? '',
      status: ok ? 'ok' : 'error',
      response_code: status ?? '',
      error: ok ? '' : JSON.stringify(payload).slice(0, 300),
    },
  });
}
return rows;

// Aggregate the run into a single Telegram summary message.
const all = $('Code · Build Log Rows').all().map((r) => r.json);
const total = all.length;
const ok = all.filter((r) => r.status === 'ok').length;
const errors = total - ok;
const byType = all.reduce((acc, r) => {
  if (r.status !== 'ok') return acc;
  acc[r.signal_type] = (acc[r.signal_type] || 0) + 1;
  return acc;
}, {});
const topSignals = Object.entries(byType)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 6)
  .map(([k, v]) => `• ${k}: ${v}`)
  .join('\n');
const when = $('Set · Run Globals').first().json.RUN_AT_CET;
const lines = [
  `*RSG Hiring Signals · Daily Ingest*`,
  `_${when} CET_`,
  ``,
  `Ingested: *${ok}/${total}* signals  (errors: ${errors})`,
  topSignals ? `\n${topSignals}` : '',
].filter(Boolean);
return [{ json: { text: lines.join('\n') } }];
